// One-off: same idea as backfill-images.mjs, but for the handful of posts
// whose DB slug (generated by the old seed-science.mjs's own title-to-slug
// logic) doesn't match the live site's actual WordPress slug, so the
// slug-guessing backfill 404'd on them. Mapped by hand from the live
// Science section's real URLs.
import { PrismaClient } from "@prisma/client";
import { fetchArticle } from "./parse.mjs";

const prisma = new PrismaClient();

const dbSlugToLiveUrl = {
  "why-cant-humans-run-100-kmh-the-biological-and-physics-limits-explained":
    "https://whyisitnotpossible.com/why-cant-humans-run-100-kmh-biological-and-physics-limits/",
  "why-flying-like-superheroes-is-physically-impossible":
    "https://whyisitnotpossible.com/why-flying-like-superheroes-is-impossible/",
  "why-solar-panels-can-never-convert-100-of-sunlight-into-electricity":
    "https://whyisitnotpossible.com/why-solar-panels-can-never-convert-100-percent-sunlight-into-electricity/",
  "why-no-engine-can-convert-100-of-fuel-energy-into-work":
    "https://whyisitnotpossible.com/why-100-percent-of-fuel-can-never-be-converted-into-work/",
  "why-landing-on-the-sun-is-impossible-the-physics-and-heat-explained":
    "https://whyisitnotpossible.com/why-landing-on-the-sun-is-impossible/",
  "why-we-cant-see-the-entire-universe-the-science-behind-the-observable-universe":
    "https://whyisitnotpossible.com/why-we-cant-see-the-entire-universe/",
  "why-cameras-cannot-capture-the-world-exactly-as-human-eyes-see-it":
    "https://whyisitnotpossible.com/why-cameras-cannot-capture-the-world/",
};

async function main() {
  let updated = 0;
  let failed = 0;

  for (const [slug, liveUrl] of Object.entries(dbSlugToLiveUrl)) {
    const post = await prisma.post.findUnique({ where: { slug }, select: { id: true, title: true, coverImageUrl: true } });
    if (!post) {
      console.log(`- no DB post with slug: ${slug}`);
      continue;
    }
    if (post.coverImageUrl) {
      console.log(`- already has image, skipping: ${post.title}`);
      continue;
    }
    try {
      const article = await fetchArticle(liveUrl);
      if (!article.coverImageUrl) {
        console.log(`- no image on live page: ${post.title}`);
        continue;
      }
      await prisma.post.update({ where: { id: post.id }, data: { coverImageUrl: article.coverImageUrl } });
      updated++;
      console.log(`+ backfilled: ${post.title}`);
    } catch (err) {
      failed++;
      console.error(`! failed: ${post.title}\n  ${err.message}`);
    }
  }

  console.log(`\nDone. Updated ${updated}, failed ${failed}.`);
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
